// === Tab: mySketch.js ===
// This is the supporting structure for a WebGL2 shader.
// The inputs are the screen resolution, a sequential number
// representing the number of milliseconds since the start
// of the animation and the mouse coordinates along with the
// mouse click, which is either 1 if pressed and otherwise 0.

p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

let theShader, mouseZ = 0;

function mousePressed() {
	mouseZ = 1;
}

function mouseReleased() {
	mouseZ = 0;
}

function windowResized() {
  resizeCanvas(4/3*windowHeight, windowHeight);
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2402483/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  canvas = createCanvas(4/3*windowHeight, windowHeight, WEBGL);
	canvas.position(140,0);
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0), mouseZ]);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}


// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; in vec2 aTexCoord; out vec2 vTexCoord;
void main() { vTexCoord = aTexCoord; vec4 positionVec4 = vec4(aPosition, 1.0);  
positionVec4.xy = positionVec4.xy * 2.0 - 1.0; gl_Position = positionVec4; }

// === Tab: frag.glsl ===
#version 300 es
precision highp float;
out vec4 O;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_mouse;
#define mouse vec3(u_mouse.xy/R,u_mouse.z)
#define FC gl_FragCoord.xy
#define R u_resolution
#define T u_time
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.8*cos(6.3*(a)+vec3(0,83,21)))
#define lum(a) dot(vec3(.2126,.7152,.0722),a)
#define anim pow(S(.0,1.,sin(T)),2.)

float tor(vec3 p, vec2 s) {
	vec2 c=vec2(length(p.xy)-s.x,p.z);
	return length(c)-s.y;
}

float map(vec3 p) {
	float d=mix(length(p)-(1.-sin(T*10.+40.*dot(p.xz,p.yz))*.02), tor(p,vec2((1.-sin(T*10.+40.*atan(p.x,p.y))*.02),.5)),anim);
	return d*.2;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
void cam(inout vec3 p) {
	if (mouse.z>.0) {
		p.yz*=rot(-mouse.y*6.2+3.14);
		p.xz*=rot(3.14-mouse.x*6.3);
	} else {
		p.xz*=rot(-T*.731);
	}
}
float shadow(vec3 p, vec3 rd) {
	float shd=1., maxd=length(rd-p);
	vec3 l=N(rd-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i);
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd, 24.*i/d);
		i+=d;
	}
	return shd;
}

void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-5),
	rd=N(vec3(uv,1.3)),
	lp=vec3(-10,10,-10);
	cam(p); cam(rd); cam(lp);
	float dd=.0, at=.0;
	for (float i=.0; i++<400.;) {
		float d=map(p);
		if (abs(d)<1e-3) {
			vec3 n=norm(p), l=N(lp-p);
			float shd=shadow(p+n*3e-3,lp);
			col+=(.2+shd*max(.0,dot(l,n)))*mix(hue(T*1.+dot(p.xz,p.yz)*4.),hue(T*.87+atan(p.x,p.y)*4./6.28318),anim);
			col+=pow(clamp(dot(reflect(rd,n),l)*.5+.5,.6,1.),63.);
			col/=1.+exp(-col*col);
			col+=lum(col);
			col=sqrt(col);
			at*=4.;
			col+=at*at;
			break;
		}
		if (d>3.) {
			col=step(max(abs(uv.x)-1.,abs(uv.y)-.125),.0)*mix(vec3(.1,.2,.3),vec3(.01,.4,.6),1.25*length(uv));
			break;
		}
		p+=rd*d;
		dd+=d;
		at+=.05*(.05/dd);
	}
	O=vec4(col,1);
}

